"""Adapt the verified culture experiment to unchanged CTRP inputs and grids."""
import hashlib,json
from pathlib import Path
BASE=Path('outputs/erastin_prism_culture_comparison');OUT=Path('outputs/erastin_ctrp_culture_comparison')
known={r['path']:r['sha256'] for r in json.load(open(BASE/'artifact_manifest.json'))['files']}
names=['culture_features.py','fit_helpers.py','model_helpers.py','metric_helpers.py','weighted_mlp.py','make_splits.py','evaluate.py','run_comparison.py','validate_preflight.py','review_comparison.py','report_comparison.py']
def replace(text,a,b):
    assert a in text,a
    return text.replace(a,b)
for n in names:
    data=(BASE/n).read_bytes();assert hashlib.sha256(data).hexdigest()==known[n];text=data.decode()
    if n=='culture_features.py':
        text=replace(text,'assert not recipe or match is not None',"assert not recipe or match is not None or m.SerumFreeMedia=='True'\n        # An explicit serum-free flag does not supply a numeric FBS percentage.\n        # Preserve that unreported value as missing rather than inferring zero.")
    if n=='run_comparison.py':
        text=replace(text,'PRISM','CTRP');text=replace(text,'outputs/erastin_prism_direct_comparison','outputs/erastin_elastic_net_comparison')
        text=replace(text,'train_lineages=20,test_lineages=20','train_lineages=23,test_lineages=23')
        text=replace(text,"for name in ['weighted_mlp.py','model_helpers.py','metric_helpers.py','evaluate.py','make_splits.py']:assert sha(OUT/name)==known[name]", "for name in ['weighted_mlp.py','model_helpers.py','metric_helpers.py','make_splits.py']:assert sha(OUT/name)==known[name]\n    templates=WS/'outputs/erastin_prism_culture_comparison';tk={v['path']:v['sha256'] for v in json.load(open(templates/'artifact_manifest.json'))['files']}\n    for name in ['culture_features.py','fit_helpers.py','run_comparison.py','validate_preflight.py','review_comparison.py','report_comparison.py','evaluate.py']:\n        assert sha(templates/name)==tk[name];records.append(dict(path=str((templates/name).relative_to(WS)),sha256=tk[name]))\n    for name in ['fit_helpers.py','evaluate.py']:assert sha(OUT/name)==tk[name]")
        text=replace(text,'samples=386,identity_groups=379,lineages=20,source_target=old[\'response_source\'],target=old[\'target\']',"samples=744,identity_groups=733,lineages=23,excluded_samples=old['excluded_samples'],ampulla_handling=old['ampulla_handling'],source_target='Unchanged archived CTRP harmonized erastin AUC; source archive DOI 10.5281/zenodo.22125121. Original upstream AUC generation recipe remains unverified.',target='Negative saved harmonized CTRP erastin AUC; higher means more sensitive. Exact prior target array, no clipping or calibration.'")
        text=replace(text,"excluded_fields='PlateCoating is constant None in all 386; SerumFreeMedia has only False among 367 known and 19 missing, redundant with medium missingness. ModelDerivationMaterial, ModelTreatment and CulturedResistanceDrug are entirely empty. Exact full recipe not encoded separately from its one-to-one medium code.'", "excluded_fields='Fixed PRISM covariate set retained. PlateCoating is constant None in all 744; ModelDerivationMaterial and CulturedResistanceDrug are entirely empty. ModelTreatment has one EBV annotation and is outside the fixed set. SerumFreeMedia has 703 False, one True and 40 missing: no new serum-free predictor is added. The one explicit serum-free recipe has no numeric FBS percentage and is median-imputed with an indicator, without inferring zero. Exact full recipe not separately encoded from its one-to-one medium code.'")
        text=replace(text,"primary_metrics=old['primary_metrics'],secondary_metrics=old['secondary_metrics']", "primary_metrics=['pooled_spearman','pooled_rmse','pooled_r2','macro_all_rmse'],secondary_metrics=['macro_large_rmse','pooled_pearson','pooled_mae'],metric_aliases={'macro_all_rmse':'previous macro23_rmse','macro_large_rmse':'previous macro19_rmse'}")
        text=replace(text,"limitations=old['limitations']+", "limitations=[old['limitations'],old['selection_limitation']]+");text=replace(text,'2026111401','2026111501')
        text=replace(text,'Serum % extracted by explicit % FBS regex;', 'Serum % extracted by explicit % FBS regex; the one serum-free recipe without explicit FBS % is retained as missing, not zero;')
    if n=='validate_preflight.py':
        text=replace(text,"len(s['ids'])==386 and len(set(s['groups']))==379 and len(set(s['lineage']))==20", "len(s['ids'])==744 and len(set(s['groups']))==733 and len(set(s['lineage']))==23")
        text=replace(text,"s['meta'].serum_percent.isna().sum()==19 and s['meta'].medium_code.eq(MISSING).sum()==19", "s['meta'].serum_percent.isna().sum()==41 and s['meta'].medium_code.eq(MISSING).sum()==40\n    special=s['meta'][s['meta'].raw_SerumFreeMedia.eq('True')];assert len(special)==1 and special.serum_percent.isna().all() and special.medium_code.ne(MISSING).all()")
        text=replace(text,'(308,78)','(595,149)');text=replace(text,"len(set(s['lineage'][a]))==20", "len(set(s['lineage'][a]))==23");text=replace(text,'all_20_lineages_on_both_outer_sides','all_23_lineages_on_both_outer_sides')
    if n=='review_comparison.py':
        text=replace(text,'(308,78)','(595,149)');text=replace(text,"m['train_n']==308 and m['test_n']==78 and m['train_lineages']==m['test_lineages']==20", "m['train_n']==595 and m['test_n']==149 and m['train_lineages']==m['test_lineages']==23")
        text=replace(text,'scores_checked==176500','scores_checked==174500');text=replace(text,'all_20_lineages_in_both_outer_sets','all_23_lineages_in_both_outer_sets');text=replace(text,'2026111402','2026111502');text=replace(text,'lineages=20','lineages=23');text=replace(text,'erastin_prism_culture_comparison_results.zip','erastin_ctrp_culture_comparison_results.zip')
        text=replace(text,"for key in KEYS:assert abs(a[key+'_mean']-b[key+'_mean'])<1e-11", "for key in ['pooled_spearman','pooled_rmse','pooled_r2','macro_all_rmse','macro_large_rmse']:\n                oldkey={'macro_all_rmse':'macro23_rmse','macro_large_rmse':'macro19_rmse'}.get(key,key);assert abs(a[key+'_mean']-b[oldkey+'_mean'])<1e-11")
    if n=='report_comparison.py':
        text=replace(text,'PRISM','CTRP');text=replace(text,'Macro-20','Macro-23');text=replace(text,'macro-20','macro-23');text=replace(text,'Macro-13','Macro-19');text=replace(text,'range(20),labels','range(23),labels');text=replace(text,'for i in range(20):','for i in range(23):');text=replace(text,'figsize=(10.8,8)','figsize=(10.8,9)');text=replace(text,'20 lineage-specific','23 lineage-specific')
        text=replace(text,'369 adherent, 12 mixed, 4 suspension, 1 unknown','548 adherent, 45 mixed, 148 suspension, 3 unknown');text=replace(text,'367/386 annotated; 55 distinct MF codes','704/744 annotated; 87 distinct MF codes');text=replace(text,'Explicit % FBS in each of the 367 nonempty recipes; training-median imputation for 19 missing values, plus a missingness indicator.', 'Explicit % FBS in 703 recipes; training-median imputation for 41 unknown percentages (40 absent media plus one serum-free recipe with no numeric FBS %), plus a missingness indicator. No zero inferred.')
        text=replace(text,'Excluded fields have no measured contrast: PlateCoating is the literal None for all 386 lines; all 367 nonmissing SerumFreeMedia flags are False, with the same 19 missing-media rows. ModelDerivationMaterial, ModelTreatment and CulturedResistanceDrug are entirely empty.', 'The same PRISM covariate set is retained. PlateCoating is the literal None for all 744 lines; ModelDerivationMaterial and CulturedResistanceDrug are empty. ModelTreatment has one EBV record and is outside the fixed covariate set. SerumFreeMedia has 703 False, one True and 40 missing; no extra serum-free flag is added. The True recipe lacks explicit FBS % and remains missing numerically.')
        text=replace(text,'Outcome: [CTRP Repurposing 20Q2 v1](https://doi.org/10.6084/m9.figshare.20564034.v1), erastin BRD-A25004090-001-08-4, HTS002 secondary-screen dose-response AUC.', 'Outcome: unchanged harmonized CTRP erastin AUC from the [recorded redistribution archive](https://doi.org/10.5281/zenodo.22125121). Archive checksums were verified in the original preparation; the exact upstream AUC generation recipe remains unverified.')
        text=replace(text,'78-line test set','149-line test set');text=replace(text,'Original AUC values above 1 remain unchanged.', 'The original harmonized CTRP target array is retained without transformation beyond its existing sign convention.')
        text=replace(text,'386 cell lines, 379 identity groups, 20 lineages.', '744 cell lines, 733 identity groups, 23 lineages. Cervix remains excluded as in the baseline.');text=replace(text,'308 training and 78 testing lines','595 training and 149 testing lines');text=replace(text,'Every inner training fold contains all 20 lineages; inner validation contains 17–20.', 'Every inner training fold contains all 23 lineages; validation contains 22. The single outer-training Ampulla line remains in every inner training fit and is never used for inner validation.');text=replace(text,'alpha 1/10/100/1,000','alpha 10/100')
        text=replace(text,'This is an exploratory internal CTRP comparison informed by earlier results.', 'This is an exploratory internal CTRP comparison informed by earlier results. The five-gene panel was chosen after earlier held-out importance analysis on these same splits; tuning inside training does not remove this earlier test-informed selection.')
        text=replace(text,"max(.20,float(repeat.rmse.max())*1.03)","max(.18,float(repeat.rmse.max())*1.03)")
    (OUT/n).write_text(text)
print('PREPARED',len(names),'script files')
